package com.sunmo.stockplatform.scanner.application;
import com.sunmo.stockplatform.candle.application.CandleSnapshot;import com.sunmo.stockplatform.candle.domain.StockCandle;import com.sunmo.stockplatform.scanner.domain.*;import org.springframework.stereotype.Component;import java.math.*;import java.util.List;
@Component
public class ScannerEvaluator {
 public record Metrics(boolean ready,BigDecimal changeRate,BigDecimal volumeRatio,BigDecimal score,String reason){}
 public Metrics calculate(CandleSnapshot current,List<StockCandle> previous){if(previous.size()<6)return new Metrics(false,null,null,null,"INSUFFICIENT_HISTORY");BigDecimal sum=previous.stream().map(c->BigDecimal.valueOf(c.getVolume())).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal average=sum.divide(BigDecimal.valueOf(6),6,RoundingMode.HALF_UP);if(average.signum()==0)return new Metrics(false,null,null,null,"UNDEFINED_BASELINE");BigDecimal ratio=BigDecimal.valueOf(current.volume()).divide(average,6,RoundingMode.HALF_UP);BigDecimal base=previous.getFirst().getClose();if(base.signum()<=0)return new Metrics(false,null,ratio,null,"INVALID_BASELINE");BigDecimal change=current.close().subtract(base).divide(base,8,RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100)).setScale(6,RoundingMode.HALF_UP);return new Metrics(true,change,ratio,change.add(ratio).setScale(6,RoundingMode.HALF_UP),"READY");}
 public boolean matches(ScannerSetting setting,Metrics m,CandleSnapshot c,BigDecimal daily){if(!m.ready()||c.close().compareTo(setting.getMinPrice())<0||c.tradingValue().compareTo(setting.getMinFiveMinuteTradingValue())<0)return false;if(daily==null||daily.compareTo(setting.getMinDailyTradingValue())<0)return false;return switch(setting.getType()){case VOLUME->m.volumeRatio().compareTo(setting.getMinVolumeRatio())>=0;case PRICE_RISE->m.changeRate().compareTo(setting.getMinChangeRate())>=0;case MOMENTUM->m.volumeRatio().compareTo(setting.getMinVolumeRatio())>=0&&m.changeRate().compareTo(setting.getMinChangeRate())>=0;};}
}
